<template><section class="patient-page"><header class="patient-page-header"><div><p class="eyebrow">FINANCE</p><h1>Payments & Receipts</h1><p class="page-subtitle">ขายบริการ รับชำระ และตรวจสอบใบเสร็จ</p></div><button @click="load">รีเฟรช</button></header><form class="form-card" @submit.prevent="sell"><h2>ออกใบเสร็จบริการ</h2><div class="form-grid"><label>Patient ID / HN<input v-model="sale.patient" required placeholder="เช่น 1 หรือ HN"></label><label>บริการ<select v-model="sale.serviceId" required><option value="" disabled>เลือกบริการ</option><option v-for="item in services" :key="item.id" :value="String(item.id)">{{ item.name }} · {{ item.price }} บาท</option></select></label><label>วิธีชำระเงิน<select v-model="sale.method" required><option v-for="item in methods" :key="item.code" :value="item.code">{{ item.name }}</option></select></label><label>ยอดชำระ<input :value="saleAmount.toFixed(2)" disabled></label></div><button class="primary" type="submit">ออกใบเสร็จ</button></form><p v-if="errorMessage" class="error">{{ errorMessage }}</p><div v-if="loading" class="state-card">กำลังโหลด...</div><div v-else-if="!receipts.length" class="state-card">ยังไม่มีใบเสร็จ</div><div v-else class="patient-results"><article v-for="receipt in receipts" :key="receipt.id" class="patient-result-card"><div><span class="patient-hn">{{ receipt.receiptNumber }} · {{ receipt.branchCode }}</span><h2>{{ receipt.patientName }}</h2><p>{{ new Date(receipt.issuedAt).toLocaleString('th-TH') }}</p></div><div><strong>{{ Number(receipt.paid).toFixed(2) }} บาท</strong><p>{{ receipt.status }}</p><button v-if="receipt.status !== 'VOIDED'" class="secondary" @click="reverse(receipt.id)">ยกเลิกใบเสร็จ</button></div></article></div></section></template>
<script setup lang="ts">import { computed, onMounted, ref } from 'vue'; import { createSale, listPaymentMethods, listReceipts, reverseReceipt, type PaymentMethod, type ReceiptSummary } from '@/api/payments'; import { getServices, type ServiceOption } from '@/api/catalog'; import { searchPatients } from '@/api/patients'; const receipts=ref<ReceiptSummary[]>([]); const methods=ref<PaymentMethod[]>([]); const services=ref<ServiceOption[]>([]); const loading=ref(false); const errorMessage=ref(''); const sale=ref({patient:'',serviceId:'',method:''}); const selectedService=computed(()=>services.value.find(s=>String(s.id)===sale.value.serviceId)); const saleAmount=computed(()=>Number(selectedService.value?.price??0)); async function load(){loading.value=true;errorMessage.value='';try{receipts.value=(await listReceipts()).items; if(!methods.value.length) methods.value=await listPaymentMethods(); if(!services.value.length) services.value=await getServices(); if(!sale.value.method) sale.value.method=methods.value[0]?.code??''; if(!sale.value.serviceId) sale.value.serviceId=String(services.value[0]?.id??'')}catch(e){errorMessage.value=e instanceof Error?e.message:'เกิดข้อผิดพลาด'}finally{loading.value=false}} async function sell(){try{const raw=sale.value.patient.trim();let patientId=Number(raw);if(raw.length>6){const result=await searchPatients(raw);const match=result.items.find(p=>p.hn===raw);if(!match)throw new Error(`ไม่พบผู้ป่วย HN ${raw}`);patientId=match.id}if(!saleAmount.value)throw new Error('ไม่พบราคาบริการ');await createSale({patientId,branchCode:'RP',items:[{type:'SINGLE_VISIT',referenceId:Number(sale.value.serviceId),quantity:1}],payments:[{paymentMethodCode:sale.value.method,amount:saleAmount.value}]});sale.value.patient='';await load()}catch(e){errorMessage.value=e instanceof Error?e.message:'ออกใบเสร็จไม่สำเร็จ'}} async function reverse(id:number){const reason=window.prompt('เหตุผลที่ยกเลิกใบเสร็จ');if(!reason?.trim())return;try{await reverseReceipt(id,reason);await load()}catch(e){errorMessage.value=e instanceof Error?e.message:'เกิดข้อผิดพลาด'}} onMounted(load)</script>
